sword-toggle:hover{background:#f2f5f9;color:var(--navy)}.password-toggle:focus-visible{outline:2px solid #7891b5;outline-offset:1px}.password-toggle svg{width:20px;height:20px;display:block}.password-toggle .eye-off{display:none}.password-toggle[aria-pressed="true"] .eye-on{display:none}.password-toggle[aria-pressed="true"] .eye-off{display:block}.options{display:flex;justify-content:space-between;align-items:center;margin:-1px 0 22px;font-size:12px}.remember{display:flex;align-items:center;gap:8px;color:#5c6c84}.forgot{color:var(--red)}.signin{width:100%;height:50px;border:0;border-radius:7px;background:var(--red);color:#fff;font-size:14px;font-weight:800;cursor:pointer}.divider{display:flex;align-items:center;gap:13px;color:#8a96a8;font-size:12px;margin:26px 0}.divider:before,.divider:after{content:"";height:1px;background:#e4e9ef;flex:1}.secure{height:48px;border:1px solid #d9e0e9;border-radius:7px;display:flex;align-items:center;justify-content:center;gap:9px;font-size:13px;font-weight:700}.error{background:#fff1f3;border:1px solid #facad1;color:#a11d31;border-radius:8px;padding:11px 13px;margin:0 0 18px;font-size:13px}.feature-bar{position:fixed;left:0;right:0;bottom:0;height:82px;background:#06275c;color:#fff;z-index:20;display:grid;grid-template-columns:repeat(6,1fr) 180px;align-items:center;padding:0 28px;box-shadow:0 -5px 16px rgba(6,39,92,.08)}.feature{padding:0 18px;border-right:1px solid rgba(255,255,255,.12);font-size:10px;line-height:1.35}.feature strong{font-size:11px;display:block;margin-bottom:2px;letter-spacing:.1px}.feature-logo{width:150px;height:58px;object-fit:contain;justify-self:end}
html[dir="rtl"] body{font-family:Tahoma,Arial,sans-serif}html[dir="rtl"] .language-options{right:auto;left:0}html[dir="rtl"] .language-options button{text-align:right}html[dir="rtl"] .input-wrap .field-icon{left:auto;right:14px}html[dir="rtl"] .input-wrap input{padding:0 48px 0 15px;text-align:right}html[dir="rtl"] .input-wrap.password input{padding-left:52px;padding-right:48px}html[dir="rtl"] .password-toggle{right:auto;left:7px}html[dir="rtl"] .options{direction:rtl}html[dir="rtl"] .remember{direction:rtl}.hidden-lang{display:none!important}
@media(max-width:1040px){.shell{grid-template-columns:1fr}.visual{display:none}.login-side{min-height:calc(100vh - 74px);padding:70px 20px 105px}.feature-bar{height:74px;grid-template-columns:repeat(3,1fr)}.feature:nth-child(n+4),.feature-logo{display:none}}@media(max-width:600px){.login-card{padding:28px 20px}.card-logo{width:210px;height:95px}.login-card h2{font-size:27px}.top-actions{top:18px;left:20px;right:20px}.home-link,.language-switch{font-size:13px}.feature-bar{grid-template-columns:1fr 1fr;padding:0 12px}.feature:nth-child(3){display:none}.feature{padding:0 10px}.options{font-size:11px}}
