<script>
(function(){
  const input=document.getElementById('login-password');
  const toggle=document.getElementById('password-toggle');
  if(input&&toggle){toggle.addEventListener('click',function(){const showing=input.type==='text';input.type=showing?'password':'text';toggle.setAttribute('aria-pressed',showing?'false':'true');toggle.setAttribute('aria-label',showing?'Show password':'Hide password');input.focus({preventScroll:true});try{input.setSelectionRange(input.value.length,input.value.length)}catch(e){}});}
  const translations={
    en:{home:'Home',welcome:'Welcome back',subtitle:'Sign in to the UNIFCO business platform.',emailLabel:'Email address',emailPlaceholder:'Enter your email',passwordLabel:'Password',passwordPlaceholder:'Enter your password',remember:'Remember me',forgot:'Forgot password?',signin:'Sign in',or:'or',secureAccess:'Secure access',secureTitle:'◉ SECURE & COMPLIANT',secureText:'JWT Authentication',roleTitle:'◇ ROLE BASED ACCESS',roleText:'Granular Permissions'},
    ar:{home:'الصفحة الرئيسية',welcome:'مرحباً بعودتك',subtitle:'سجّل الدخول إلى منصة UNIFCO للأعمال.',emailLabel:'البريد الإلكتروني',emailPlaceholder:'أدخل بريدك الإلكتروني',passwordLabel:'كلمة المرور',passwordPlaceholder:'أدخل كلمة المرور',remember:'تذكرني',forgot:'هل نسيت كلمة المرور؟',signin:'تسجيل الدخول',or:'أو',secureAccess:'دخول آمن',secureTitle:'◉ آمن ومتوافق',secureText:'مصادقة عبر JWT',roleTitle:'◇ صلاحيات مبنية على الأدوار',roleText:'صلاحيات دقيقة ومتدرجة'}
  };
  const langButton=document.getElementById('language-switch');
  const langOptions=document.getElementById('language-options');
  const langLabel=document.getElementById('language-label');
  function setLanguage(lang){const dict=translations[lang]||translations.en;document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';langLabel.textContent=lang==='ar'?'العربية':'English';document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.getAttribute('data-i18n');if(dict[key])el.textContent=dict[key];});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const key=el.getAttribute('data-i18n-placeholder');if(dict[key])el.setAttribute('placeholder',dict[key]);});localStorage.setItem('unifco-login-lang',lang);langOptions.classList.remove('show');langButton.setAttribute('aria-expanded','false');}
  langButton.addEventListener('click',()=>{const open=langOptions.classList.toggle('show');langButton.setAttribute('aria-expanded',open?'true':'false');});
  langOptions.querySelectorAll('button[data-lang]').forEach(btn=>btn.addEventListener('click',()=>setLanguage(btn.dataset.lang)));
  document.addEventListener('click',e=>{if(!e.target.closest('.language-menu')){langOptions.classList.remove('show');langButton.setAttribute('aria-expanded','false');}});
  setLanguage(localStorage.getItem('unifco-login-lang')||'en');
})();
</script>
